(window.TNQ=window.TNQ||[]).push({"terms":{"성숙":{"d":"경험이나 훈련과 관계없이 유전적으로 정해진 순서대로 진행되는 변화입니다.","r":[]},"집단무의식":{"d":"융 이론에서 인류가 조상으로부터 물려받아 공유하는 보편적 무의식이다.","r":[]},"그림자":{"d":"융 이론에서 자신이 받아들이기 꺼리는 어두운 면이 억압된 원형이다.","r":[]},"사회적 관심":{"d":"아들러 이론에서 타인과 공동체에 관심을 갖고 협력하려는 선천적 잠재력이다.","r":[]},"자아":{"d":"현실원리에 따라 원초아와 초자아를 조정하고 현실에 적응하게 하는 성격의 실행자이다.","r":[]},"실수행위":{"d":"말실수처럼 무의식이 드러나는 것으로 프로이트가 무의식의 증거로 본 행위입니다.","r":[]},"미시체계":{"d":"개인이 직접 대면하며 상호작용하는 가족, 친구, 학교 등의 가장 가까운 환경이다.","r":[]},"대상영속성":{"d":"눈에 보이지 않아도 대상이 계속 존재한다는 것을 아는 능력으로 감각운동기에 획득한다.","r":[]},"상상적 관중":{"d":"청소년이 자신이 타인의 주목 대상이라고 믿어 다른 사람의 시선을 의식하는 자기중심성이다.","r":[]},"개성화":{"d":"융 이론에서 중년기에 내면으로 에너지가 향하며 의식과 무의식을 통합하여 진정한 자기가 되는 과정이다.","r":[]},"자아통합":{"d":"에릭슨이 노년기 과제로 본 것으로 지나온 삶을 의미 있게 받아들이는 것이다.","r":[]},"문화변용":{"d":"둘 이상의 문화가 지속적으로 접촉하여 한쪽 또는 양쪽 문화에 변화가 생기는 현상이다.","r":[]},"문화마찰":{"d":"서로 다른 문화가 접촉하면서 가치와 행동양식의 차이로 갈등이 생기는 현상이다.","r":[]},"문화적 역량":{"d":"다양한 문화적 배경의 클라이언트를 이해하고 효과적으로 실천할 수 있는 사회복지사의 능력이다.","r":[]},"발달과업":{"d":"각 발달단계에서 성취해야 할 과제로, 이를 이루면 다음 단계 적응이 쉬워진다고 본다.","r":[]},"결정적 시기":{"d":"특정 발달이 이루어지기에 가장 적합하며, 이 시기를 놓치면 이후 회복이 어려운 시기를 말한다.","r":[]},"분화와 통합":{"d":"전체적이고 미분화된 상태에서 특수한 기능으로 나뉘고, 나뉜 기능이 다시 조직되는 발달 원리이다.","r":[]},"발달단계":{"d":"발달이 질적으로 구분되는 일정한 시기로 나눈 것이며, 단계별로 행동 특성과 과업이 다르다.","r":[]},"사정":{"d":"사회복지실천에서 클라이언트의 문제와 환경을 파악하고 평가하는 과정이다.","r":[]},"이상행동":{"d":"사회문화적 규범에서 벗어나거나 본인과 타인에게 고통을 주는 행동이며, 시대와 문화에 따라 기준이 달라진다.","r":[]},"정신질환 진단 및 통계편람":{"d":"미국정신의학회가 발간한 정신장애 진단분류체계로 약칭 DSM이라고 한다.","r":[]},"생태체계이론":{"d":"인간과 환경을 상호작용하는 체계로 보고 환경을 여러 수준의 체계로 나누어 설명하는 이론이다.","r":[]},"체계이론":{"d":"인간과 환경을 서로 영향을 주고받는 요소들의 집합인 체계로 보는 관점이다.","r":[]},"넥엔트로피":{"d":"체계 내 질서와 구조가 증가하여 체계가 유지되고 발전하는 상태로, 엔트로피와 반대 개념이다.","r":[]},"엔트로피":{"d":"체계 내 에너지가 소진되어 무질서해지고 붕괴로 향하는 경향이며, 폐쇄체계에서 주로 나타난다.","r":[]},"폐쇄체계":{"d":"환경과 에너지, 정보를 교환하지 않거나 경계가 닫혀 있어 엔트로피가 증가하는 체계이다.","r":[]},"항상성":{"d":"체계가 비교적 안정적이고 지속적인 균형상태를 유지하려는 경향을 말한다.","r":[]},"경계":{"d":"체계와 환경, 또는 체계와 체계를 구분 짓는 테두리를 말한다.","r":[]},"다중종결성":{"d":"같은 출발점에서 시작해도 서로 다른 결과에 이를 수 있다는 일반체계이론 개념이다.","r":[]},"부적 환류":{"d":"체계가 목표 달성에서 벗어났다는 정보를 주어 변화를 줄이고 안정을 회복시키는 환류이다.","r":[]},"피드백":{"d":"체계의 산출이 다시 투입으로 돌아와 체계 작동을 조절하게 하는 순환 과정이다.","r":[]},"적합성":{"d":"인간의 적응 욕구와 환경이 제공하는 자원이 서로 들어맞는 정도를 말한다.","r":[]},"중간체계":{"d":"둘 이상의 미시체계 사이의 관계와 상호작용으로 구성되는 체계이다.","r":[]},"외체계":{"d":"개인이 직접 참여하지는 않지만 부모의 직장 등으로 간접적 영향을 미치는 체계이다.","r":[]},"거시체계":{"d":"문화, 이념, 정치, 법, 사회정책 등 사회 전반의 가치와 신념이 반영된 가장 바깥 수준의 체계이다.","r":[]},"시간체계":{"d":"개인이 살아가는 시대와 생애 사건의 변화가 발달에 영향을 주는 차원이다.","r":[]},"항문기":{"d":"프로이트 성심리 발달 중 배변 훈련과 관련해 양육자와 갈등을 겪는 시기이다.","r":[]},"남근기":{"d":"프로이트 성심리 발달 중 성기에 관심이 모이고 오이디푸스 콤플렉스가 나타나는 시기이다.","r":[]},"생식기":{"d":"프로이트 성심리 발달의 마지막 단계로 사춘기 이후 성숙한 이성 관계를 추구하는 시기이다.","r":[]},"리비도":{"d":"프로이트가 말한 성적 에너지로, 발달단계마다 집중되는 신체 부위가 다르다.","r":[]},"오이디푸스 콤플렉스":{"d":"남근기 남아가 어머니에게 애착을 느끼고 아버지에게 적대감을 갖는 갈등이다.","r":[]},"엘렉트라 콤플렉스":{"d":"남근기 여아가 아버지에게 애착을 느끼고 어머니에게 경쟁심을 갖는 갈등이다.","r":[]},"거세불안":{"d":"남근기 남아가 아버지에게 성기를 잃을 것이라는 두려움을 느끼는 불안이다.","r":[]},"동일시":{"d":"자신에게 중요한 사람의 태도와 특성을 받아들여 자기 것으로 삼는 심리 기제이다.","r":[]},"원초아":{"d":"쾌락원리에 따라 본능적 욕구를 즉시 충족하려는 성격의 가장 원시적 구조이다.","r":[]},"초자아":{"d":"양심과 자아이상으로 구성되며 도덕적 규범에 따라 행동하도록 하는 성격 구조이다.","r":[]},"자아이상":{"d":"초자아의 한 부분으로 부모가 칭찬하고 보상한 이상적 행동 기준을 내면화한 것이다.","r":[]},"일차적 사고과정":{"d":"원초아가 욕구를 즉각 충족하려고 환상이나 상상으로 긴장을 해소하는 비논리적 사고이다.","r":[]},"2차적 사고과정":{"d":"자아가 현실을 고려해 논리적으로 문제를 해결하는 합리적 사고이다.","r":[]},"현실원칙":{"d":"자아가 욕구 충족을 현실 여건에 맞게 미루거나 조절하도록 하는 원리이다.","r":[]},"무의식":{"d":"자각하지 못하지만 행동에 영향을 주는 정신 영역이며, 프로이트 이론의 핵심 개념이다.","r":[]},"방어기제":{"d":"불안과 갈등에서 자아를 보호하기 위해 무의식적으로 현실을 왜곡하는 심리 기제이다.","r":[]},"합리화":{"d":"받아들이기 어려운 행동이나 결과에 그럴듯한 이유를 대어 정당화하는 방어기제이다.","r":[]},"억압":{"d":"수용할 수 없는 생각과 기억을 무의식으로 밀어 넣어 의식에 떠오르지 않게 하는 방어기제이다.","r":[]},"투사":{"d":"자신의 용납할 수 없는 충동이나 감정을 타인의 것으로 돌리는 방어기제이다.","r":[]},"반동형성":{"d":"무의식적 욕구와 반대되는 태도나 행동을 보이는 방어기제이다.","r":[]},"전치":{"d":"특정 대상에게 느낀 감정을 덜 위협적인 다른 대상으로 옮겨 표출하는 방어기제이다.","r":[]},"내면화":{"d":"타인의 가치와 태도를 자신의 것으로 받아들여 내부로 들이는 과정이다.","r":[]},"페르소나":{"d":"융 이론에서 사회적 요구에 부응하기 위해 쓰는 외적 인격, 곧 가면을 말한다.","r":[]},"아니무스":{"d":"융 이론에서 여성 내부에 있는 남성성을 가리키는 원형이다.","r":[]},"개인심리이론":{"d":"아들러의 이론으로 열등감 극복과 우월 추구, 사회적 관심을 인간 행동의 동기로 본다.","r":[]},"열등감":{"d":"아들러가 모든 인간이 지닌다고 본 보편적 감정으로 성장의 동기가 된다.","r":[]},"가상적 목표":{"d":"아들러 이론에서 개인이 삶의 방향으로 삼는 현실에서 검증되지 않은 주관적 목표이다.","r":[]},"생활양식":{"d":"아들러 이론에서 개인이 삶의 문제에 대처하는 독특한 방식이며, 사회적 관심과 활동성으로 유형을 나눈다.","r":[]},"심리사회적 위기":{"d":"에릭슨 이론에서 각 발달단계마다 겪는 긍정과 부정 양극 사이의 갈등이다.","r":[]},"조작적 조건형성":{"d":"스키너가 제시한 학습 원리로 행동 뒤의 결과가 이후 행동의 빈도를 좌우한다는 이론이다.","r":[]},"고전적 조건형성":{"d":"파블로프가 제시한 학습 원리로 조건자극과 무조건자극을 짝지어 반응을 학습한다.","r":[]},"강화계획":{"d":"행동에 대한 강화물을 언제 제공할지 정하는 방식이며 고정과 변동, 간격과 비율로 나뉜다.","r":[]},"변동간격계획":{"d":"일정하지 않은 시간 간격이 지난 뒤 처음 나타난 반응에 강화물을 주는 계획이다.","r":[]},"가변비율":{"d":"평균적으로 일정 횟수의 반응 뒤에 불규칙하게 강화물을 주는 계획으로 반응률이 높다.","r":[]},"부적 강화":{"d":"혐오 자극을 제거하여 바람직한 행동의 빈도를 증가시키는 것이다.","r":[]},"정적 강화물":{"d":"행동 후 제공되어 그 행동의 빈도를 증가시키는 자극으로 음식, 돈, 칭찬 등이 있다.","r":[]},"행동조성":{"d":"원하는 행동에 가까워지는 반응을 단계적으로 강화하여 복잡한 행동을 습득시키는 방법이다.","r":[]},"관찰학습":{"d":"타인의 행동과 그 결과를 관찰하는 것만으로 이루어지는 학습으로 반두라가 강조했다.","r":[]},"무조건적 긍정적 관심":{"d":"로저스 이론에서 상담자가 조건 없이 클라이언트를 수용하고 존중하는 태도이다.","r":[]},"완전히 기능하는 인간":{"d":"로저스가 자아실현을 이룬 사람의 특성을 가리킨 용어이다.","r":[]},"자아실현경향":{"d":"로저스 이론에서 인간이 가진 잠재력을 발휘하며 성장하려는 선천적 경향이다.","r":[]},"생리적 욕구":{"d":"매슬로우 욕구위계에서 음식, 수면 등 생존에 필요한 가장 하위 단계의 욕구이다.","r":[]},"자아실현의 욕구":{"d":"매슬로우 욕구위계의 최상위 단계로 잠재력을 발휘하려는 욕구이다.","r":[]},"동화와 조절":{"d":"피아제 이론에서 기존 도식으로 새 정보를 받아들이는 것과 도식을 바꾸는 것을 가리킨다.","r":[]},"평형화":{"d":"피아제 이론에서 인지적 불균형을 동화와 조절로 해소하며 환경과 조화를 이루려는 경향이다.","r":[]},"전조작기":{"d":"피아제 인지발달의 두 번째 단계로 상징놀이와 직관적 사고가 나타나나 논리적 조작은 미흡하다.","r":[]},"구체적 조작기":{"d":"피아제 인지발달 단계 중 보존개념을 획득하고 구체적 대상에 대해 논리적으로 사고하는 시기이다.","r":[]},"보존개념":{"d":"모양이 변해도 양이나 수는 변하지 않는다는 것을 이해하는 개념으로 구체적 조작기에 획득한다.","r":[]},"비가역적 사고":{"d":"변형된 상태를 원래대로 되돌려 생각하지 못하는 전조작기 아동의 사고이다.","r":[]},"전인습적 수준":{"d":"콜버그 도덕성 발달에서 처벌과 보상 같은 행동의 결과로 옳고 그름을 판단하는 수준이다.","r":[]},"인습적 수준":{"d":"콜버그 도덕성 발달에서 사회 규범과 법, 질서를 따르는 것을 옳다고 보는 수준이다.","r":[]},"보편적 윤리 지향":{"d":"콜버그 도덕성 발달의 최고 단계로 정의와 평등 같은 보편적 가치와 양심을 따른다.","r":[]},"도덕적 딜레마":{"d":"콜버그가 도덕성 단계를 파악하려고 제시한, 두 가지 도덕 가치가 충돌하는 이야기 상황이다.","r":[]},"대리적 강화":{"d":"반두라 이론에서 타인이 강화받는 모습을 관찰하는 것만으로 관찰자의 행동이 강화되는 것이다.","r":[]},"조절":{"d":"새로운 정보를 접했을 때 기존의 도식을 변경하거나 새 도식을 만드는 피아제 이론의 개념이다.","r":[]},"보존":{"d":"대상의 모양이 변해도 양이나 수는 변하지 않는다는 것을 이해하는 개념이다.","r":[]},"가역성":{"d":"변형된 것을 거꾸로 되돌려도 원래 상태가 된다고 생각할 수 있는 사고 능력이다.","r":[]},"고정간격":{"d":"정해진 시간 간격이 지난 후 처음 나타난 반응에 강화물을 주는 강화계획이다.","r":[]},"연속강화계획":{"d":"목표 행동이 나타날 때마다 강화물을 주는 계획으로 행동 습득이 빠르다.","r":[]},"간헐강화계획":{"d":"행동 중 일부에만 강화물을 주는 계획으로 소거 저항이 높다.","r":[]},"일차적 강화물":{"d":"음식, 물처럼 학습 없이도 강화 효과를 가지는 무조건 자극이다.","r":[]},"부적강화":{"d":"혐오 자극을 제거하여 바람직한 행동의 빈도를 증가시키는 것이다.","r":[]},"후인습적 수준":{"d":"콜버그 도덕성 발달에서 사회계약과 보편적 원리에 따라 법도 바뀔 수 있다고 보는 수준이다.","r":[]},"모방학습":{"d":"모델의 행동을 보고 따라 하며 행동을 습득하는 학습이다.","r":[]},"인지적 왜곡":{"d":"벡의 인지치료에서 현실을 비합리적으로 해석하는 사고 오류로 이분법적 사고, 과잉일반화 등이 있다.","r":[]},"이분법적 사고":{"d":"사건을 전부 아니면 전무의 양극단으로만 판단하는 인지적 왜곡이다.","r":[]},"과잉일반화":{"d":"한두 번의 경험을 근거로 모든 상황에 일반화하는 인지적 왜곡이다.","r":[]},"임의적 추론":{"d":"근거 없이 또는 반대 증거가 있음에도 부정적 결론을 내리는 인지적 왜곡이다.","r":[]},"개인화":{"d":"자신과 무관한 사건을 자기 탓으로 돌려 해석하는 인지적 왜곡이다.","r":[]},"분리이론":{"d":"노년기에 노인과 사회가 서로 상호작용을 줄이며 분리되는 것을 자연스럽다고 보는 이론이다.","r":[]},"활동이론":{"d":"노년기에도 활동을 유지하고 은퇴로 잃은 역할을 대체할 활동을 찾는 것이 적응에 중요하다고 보는 이론이다.","r":[]},"유동성 지능":{"d":"새로운 문제 해결과 추론, 처리 속도에 관한 지능으로 성인기 이후 감퇴한다.","r":[]},"신뢰 대 불신":{"d":"에릭슨 이론에서 영아기에 양육자와의 관계로 형성되는 심리사회적 위기이다.","r":[]},"성적 정체성":{"d":"자신이 남성인지 여성인지 인식하고 받아들이는 것을 말한다.","r":[]},"다운증후군":{"d":"염색체 이상으로 발생하며 지적장애를 동반하는 유전적 증후군이다.","r":[]},"헌팅톤병":{"d":"우성 유전으로 발병하며 중년 이후 운동장애와 인지 저하가 나타나는 유전 질환이다.","r":[]},"클라인펠터증후군":{"d":"남성에게 X염색체가 하나 더 있는 성염색체 이상이다.","r":[]},"터너증후군":{"d":"여성에게 X염색체가 하나 부족한 성염색체 이상이다.","r":[]},"혈우병":{"d":"혈액 응고 인자 결핍으로 출혈이 멎지 않는 반성유전 질환으로 주로 남성에게 나타난다.","r":[]},"원시반사":{"d":"신생아가 출생 시 보이는 무의도적 반사로 바빈스키, 모로, 파악반사 등이 있다.","r":[]},"바빈스키반사":{"d":"신생아의 발바닥을 긁으면 발가락을 부채처럼 펴는 반사이다.","r":[]},"파악반사":{"d":"손에 닿는 물건을 움켜쥐려는 신생아의 반사운동이다.","r":[]},"모로반사":{"d":"갑작스러운 자극에 팔과 다리를 펴면서 껴안으려는 신생아의 반사운동이다.","r":[]},"연하반사":{"d":"입 속의 음식물을 삼키려는 반사운동이다.","r":[]},"탐색반사":{"d":"뺨이나 입 주변에 자극을 주면 그쪽으로 고개를 돌려 입을 벌리는 반사이다.","r":[]},"배종기":{"d":"태내 발달의 첫 단계로 수정 후 수정란이 자궁벽에 착상하기까지의 시기이다.","r":[]},"양수검사":{"d":"임신 중 양수를 채취하여 태아의 염색체 이상이나 유전 결함을 확인하는 검사이다.","r":[]},"태아알콜증후군":{"d":"임신 중 어머니의 음주로 태아에게 안면기형, 성장 지연, 지적장애가 나타나는 증후군이다.","r":[]},"외배엽":{"d":"배아의 바깥층으로 신경계, 피부 등을 형성한다.","r":[]},"내배엽":{"d":"배아의 안쪽층으로 폐, 간, 소화기관 등을 형성한다.","r":[]},"분류화":{"d":"사물을 공통 속성에 따라 범주로 묶는 인지 능력으로 구체적 조작기에 발달한다.","r":[]},"서열화":{"d":"사물을 크기나 길이 등 일정한 기준으로 순서대로 배열하는 인지 능력이다.","r":[]},"자율적 도덕성":{"d":"피아제 도덕성 발달에서 규칙이 합의로 바뀔 수 있고 의도를 고려하는 단계이다.","r":[]},"일차성징":{"d":"난소, 자궁, 고환, 음경 등 생식에 필요한 기관의 발달을 말한다.","r":[]},"이차성징":{"d":"가슴 발달, 변성, 체모 등 사춘기에 나타나는 성적 성숙의 외적 징후이다.","r":[]},"안드로겐":{"d":"고환에서 분비되는 남성 호르몬으로 남성의 성적 성숙을 이끈다.","r":[]},"에스트로겐":{"d":"난소에서 분비되는 여성 호르몬으로 여성의 성적 성숙을 이끈다.","r":[]},"개인적 우화":{"d":"청소년이 자신의 경험은 특별해서 타인의 위기가 자신에게는 일어나지 않는다고 믿는 사고이다.","r":[]},"조합기술":{"d":"여러 요소를 가능한 모든 방식으로 결합하는 능력으로 사칙연산 같은 조작에 쓰인다.","r":[]},"가설연역적 사고":{"d":"가설을 세우고 논리적으로 결과를 추론하여 검증하는 형식적 조작기의 사고이다.","r":[]},"형식적 조작사고":{"d":"피아제 인지발달의 마지막 단계에서 추상적이고 논리적으로 사고하는 능력이다.","r":[]},"심리적 이유기":{"d":"청소년기에 부모로부터 심리적으로 독립하려는 시기이다.","r":[]},"자아정체감":{"d":"에릭슨 이론에서 자신에 대한 일관된 인식으로 청소년기의 핵심 과업이다.","r":[]},"역할실험":{"d":"마샤 이론에서 정체감 유예 상태에서 다양한 역할과 가치를 시험해 보는 것이다.","r":[]},"생산성 대 침체":{"d":"에릭슨 이론에서 중년기에 다음 세대를 돌보는 것과 정체되는 것 사이의 위기이다.","r":[]},"빈둥지 증후군":{"d":"자녀가 독립해 떠난 뒤 중년기 부모가 느끼는 상실감과 우울이다.","r":[]},"갱년기":{"d":"호르몬 분비 변화로 신체적 변화와 우울, 무기력감 등을 겪는 중년기의 시기이다.","r":[]},"동화주의":{"d":"이민자가 주류 문화에 흡수되어 고유 문화를 버리도록 하는 입장으로 용광로 개념과 관련된다.","r":[]},"용광로":{"d":"여러 문화가 녹아 하나의 주류 문화로 합쳐진다고 보는 동화주의 비유이다.","r":[]},"다문화주의":{"d":"여러 문화와 언어를 서로 존중하고 적극 수용하려는 입장이다.","r":[]},"2차집단":{"d":"목적 달성을 위해 계약적이고 공식적으로 맺어진 집단으로 인간 성격 형성이 목적은 아니다.","r":[]},"개방집단":{"d":"집단 진행 중에도 새로운 구성원이 들어올 수 있는 집단이다.","r":[]},"형성집단":{"d":"특정 목적을 위해 의도적으로 만든 집단이다.","r":[]},"자연집단":{"d":"자연스럽게 생겨난 집단으로 가족과 친구 집단 등이 있다.","r":[]},"사회통제":{"d":"규범과 제재로 구성원의 행동을 사회가 요구하는 방향으로 이끄는 기능이다.","r":[]}},"notes":{"2차적 사고과정과 현실원칙에 의해 지배된다":"자아는 2차적 사고과정을 쓰며 현실원칙에 따라 움직입니다.","46세 이후에 그릇된 가정을 모두 극복하고 진정한 자아를 찾는 시기라고 하였다":"굴드는 46세 이후를 그릇된 가정을 모두 벗고 참된 자아를 찾는 시기라고 했습니다.","“생산성 대 침체”라는 심리사회적 위기를 극복하게 되면 돌봄(care)의 덕목을 갖추게 된다":"에릭슨은 중년기의 생산성 대 침체라는 위기를 극복하면 돌봄의 덕목을 갖춘다고 했습니다.","각 체계들로부터 다양하고 객관적인 정보획득이 용이하다":"각 체계에서 다양하고 객관적인 정보를 쉽게 얻을 수 있습니다.","각 체계들로부터 다양한 정보획득이 용이하다":"생태체계관점은 여러 체계에서 정보를 얻기 쉽다는 장점이 있습니다.","강화계획 중에서 반응률이 가장 높다":"가변비율계획은 강화계획 중 행동이 나오는 비율이 가장 높습니다.","개인무의식과 집단무의식으로 나뉜다":"융은 무의식을 개인무의식과 집단무의식 두 가지로 나누었습니다.","개인의 성장 과정에서 나타나는 문제의 원인을 이해하는 데 도움을 제공한다":"성장 과정에서 나타나는 개인의 문제가 왜 생겼는지 이해하는 데 도움이 됩니다.","개인의 소득이 줄어들고, 상실을 경험하며 자아정체감이 저하되기도 한다":"은퇴로 소득이 줄고 상실감을 겪으며 자아정체감이 낮아지기도 합니다.","개인이 사회적 요구에 반응하기 위한 가면을 의미한다":"페르소나는 사회의 요구에 응하려고 개인이 쓰는 가면입니다.","개인적 욕구와 사회적 욕구 사이에 균형을 찾아 직업을 선택하는 시기이다":"청년기에는 개인적 욕구와 사회적 욕구의 균형을 찾아 직업을 고릅니다.","경험이나 훈련의 결과와 상관없이 진행된다":"성숙은 경험이나 훈련의 결과와 상관없이 유전적 계획에 따라 진행됩니다.","공동의 문제를 해결하고 삶의 질 향상을 위해 조직화가 가능한 대상이다":"지역사회는 공동의 문제를 풀고 삶의 질을 높이려고 조직화할 수 있는 대상입니다.","남자아이는 오이디푸스 콤플렉스(Oedipus complex)로 인한 거세불안을 경험한다":"남근기의 남자아이는 오이디푸스 콤플렉스 때문에 거세불안을 겪습니다.","노년기를 노인 개인과 사회가 동시에 상호분리를 시작하는 시기로 보는 이론이다":"분리이론은 노년기에 노인과 사회가 동시에 서로 멀어지기 시작한다고 봅니다.","노년기를 잘 보내기 위해서는 은퇴와 같은 종결되는 역할들을 대치할 수 있는 활동을 발견하는 것이 중요하다는 이론이다":"활동이론은 은퇴로 끝난 역할을 대신할 활동을 찾는 것이 노년기를 잘 보내는 길이라고 봅니다.","노년기의 발달과제로 자아통합이 중요하다고 주장하였다":"에릭슨은 노년기의 발달과제로 지나온 삶을 받아들이는 자아통합을 꼽았습니다.","다른 사람이 경험하는 위기가 자신에게는 일어나지 않으리라 믿는다":"청소년은 다른 사람에게 닥친 위기가 자기에게는 일어나지 않을 거라고 믿습니다.","다양한 문화나 언어를 공유하고 상호 존중하여 적극 수용하려는 입장을 취한다":"다문화주의는 다양한 문화와 언어를 서로 존중하고 적극 받아들이려는 입장입니다.","다양한 문화적 배경의 클라이언트를 대상으로 사회복지실천을 하기 위해서는 문화적 역량이 요구된다":"다양한 문화적 배경을 가진 클라이언트를 만나려면 문화적 역량이 필요합니다.","대상영속성(object permanence)이 형성된다":"영아기에는 눈앞에 없는 물체도 존재한다고 아는 대상영속성이 형성됩니다.","모든 사람을 자신의 관점에서만 본다":"유아기는 모든 사람을 자기 관점에서만 보는 자기중심적 사고를 합니다.","목적지향적이며 분업적 특성이 있다":"조직은 목적을 향해 움직이며 일을 나누어 하는 분업적 특성이 있습니다.","문제에 대한 총체적 이해와 접근을 용이하게 해준다":"생태체계관점은 문제를 전체적으로 이해하고 접근하기 쉽게 해 줍니다.","문제에 대한 총체적 이해와 조망을 제공한다":"생태체계관점은 문제를 총체적으로 이해하고 조망할 수 있게 합니다.","문화변용, 문화마찰 등의 용어는 문화의 역동적 특성을 나타낸다":"문화변용과 문화마찰은 문화가 계속 변하는 역동성을 보여 주는 말입니다.","미시체계 간의 상호작용에 초점을 둔다":"미시체계는 개인과 환경이 아니라 미시체계 사이의 상호작용에 초점을 둡니다.","발달 단계별 욕구를 기반으로 사회복지서비스를 개발할 수 있다":"발달 단계마다 욕구가 다르므로 이를 바탕으로 서비스를 개발할 수 있습니다.","배우자 사망 등을 겪게 되면서 심리적 우울감을 경험할 수 있다":"배우자의 죽음 등을 겪으며 노년기에는 우울감을 경험할 수 있습니다.","부모로부터 심리적, 경제적으로 독립하여 자율성을 성취하는 시기이다":"청년기는 부모에게서 심리적, 경제적으로 독립해 자율성을 이루는 시기입니다.","부모보다 또래집단의 영향력이 커진다":"청소년기에는 부모보다 또래집단의 영향력이 커집니다.","부모와 교사와의 관계, 형제관계 등을 말한다":"미시체계에는 부모와 교사의 관계, 형제관계처럼 개인과 직접 맺는 관계가 속합니다.","분화와 통합의 과정을 반복하며 이루어진다":"발달은 분화와 통합이 되풀이되면서 이루어지는 과정입니다.","비교적 안정적으로 균형 상태를 유지하기 위한 체계의 경향을 말한다":"항상성은 체계가 비교적 안정된 균형 상태를 유지하려는 경향입니다.","사회복지실천을 위한 사정도구로서 유용성을 가진다":"생태체계관점은 사회복지실천에서 사정을 위한 도구로 쓸모가 있습니다.","사회복지실천의 주요 대상이다":"가족은 사회복지실천이 주로 개입하는 대상입니다.","사회질서의 유지를 위해 법과 규칙은 준수되어야 하지만, 민주적인 절차를 통해 바뀔 수 있다고 생각한다":"후인습적 수준에서는 법과 규칙이 사회질서를 위해 지켜져야 하지만 민주적 절차로 바뀔 수 있다고 봅니다.","상상과 현실을 구분하지 못하는 사고 특징을 가진다":"유아기는 상상과 현실을 구분하지 못하는 사고 특징이 있습니다.","상상적 관중을 의식하여 작은 실수에 대해서도 번민한다":"상상적 관중은 남들이 자기를 지켜본다고 믿는 생각이며 작은 실수에도 번민하게 합니다.","생산성 대 침체성의 시기라고 하였다":"에릭슨은 중년기를 생산성 대 침체성의 시기라고 불렀습니다.","생애주기별 실천개입의 기반을 제공하였다":"에릭슨의 이론은 생애주기에 맞춘 실천개입의 기반이 되었습니다.","선천적으로 타고 나는 것이다":"우월에 대한 추구는 사람이 선천적으로 타고나는 욕구입니다.","성역할의 내면화가 이루어진다":"유아기에는 성역할이 내면화됩니다.","성인 초기의 생애 구조에 대한 평가, 중년기에 대한 가능성 탐구, 새로운 생애 구조 설계를 위한 선택 등을 과업으로 제시하였다":"레빈슨은 중년기의 과업으로 초기 생애 구조 평가, 가능성 탐구, 새 생애 구조 설계를 위한 선택을 제시했습니다.","수분과 피하지방이 감소되어 얇아지고 건조해지며 탄력성도 떨어질 수 있다":"노년기 피부는 수분과 피하지방이 줄어 얇고 건조해지며 탄력이 떨어집니다.","신체적 발달이 활발하여 제2의 성장 급등기로 불린다":"신체 발달이 활발해서 제2의 성장 급등기라고 부릅니다.","신체적 측면에서 제2의 급성장기이다":"청소년기는 신체가 급격히 자라는 제2의 급성장기입니다.","실수행위를 통해 무의식이 작용하는 증거를 파악하였다":"프로이트는 말실수 같은 실수행위에서 무의식이 작용하는 증거를 찾았습니다.","심리성적발달단계에서 생식기에 해당한다":"프로이트의 심리성적발달단계에서 청소년기는 생식기에 해당합니다.","심리적 이유기의 특징을 보인다":"청소년기는 부모에게서 심리적으로 벗어나려는 심리적 이유기의 특징을 보입니다.","아무 관계가 없는 사건들을 연결지어 생각한다":"유아기에는 서로 관계없는 사건들을 이어서 생각하기도 합니다.","어려움에 부딪힐 때 효과적으로 대처하는데 도움이 된다":"가상적 목표는 어려움에 부딪혔을 때 효과적으로 대처하도록 도와줍니다.","언어를 사회적 상호작용의 도구로 활발하게 사용하기 시작한다":"유아기에는 언어를 사회적 상호작용의 도구로 활발하게 쓰기 시작합니다.","에릭슨(E. Erikson)의 주도성 대 죄책감 단계에 해당된다":"유아기는 에릭슨의 주도성 대 죄책감 단계에 해당합니다.","영아기(0-2세)보다 발달속도가 느려진다":"유아기는 영아기보다 발달속도가 느려집니다.","예시로 음식, 돈, 칭찬 등을 들 수 있다":"정적 강화물의 예로 음식, 돈, 칭찬이 있습니다.","오래 사용하여 친근한 물건에 대한 애착심이 증가할 수 있다":"노년기에는 오래 써서 낯익은 물건에 대한 애착이 커질 수 있습니다.","외부세계에 쏟았던 에너지를 자신의 내부에 초점을 두며 개성화의 과정을 경험한다":"융은 중년기에 에너지를 자기 내부로 돌려 개성화 과정을 겪는다고 보았습니다.","음식, 물, 따뜻함 등과 같은 무조건 자극으로서 학습이 필요하지 않은 것을 말한다":"일차적 강화물은 음식, 물, 따뜻함처럼 배우지 않아도 반응하게 하는 무조건 자극입니다.","이상행동은 클라이언트가 겪는 문제의 원인이 될 수 있다":"이상행동이 있으면 그 자체가 클라이언트가 겪는 문제의 원인이 될 수 있습니다.","인간은 사회적 관심에 의해 동기화된다":"아들러는 인간이 사회적 관심에 의해 움직인다고 보았습니다.","인간은 자신의 일부로 받아들이기를 꺼리는 그림자를 가지고 있다":"그림자는 인간이 자기 일부로 받아들이기를 꺼리는 어두운 면입니다.","인간의 본성은 본래 선하다고 주장하였다":"인본주의는 인간의 본성이 본래 선하다고 봅니다.","인간의 삶과 의식 속에 내재되어 개인의 행동에 영향을 미친다":"문화는 사람의 삶과 의식 속에 스며 있어 개인의 행동에 영향을 줍니다.","인간의 욕구를 파악할 수 있는 근거를 마련하였다":"매슬로우는 인간의 욕구가 무엇인지 파악할 근거를 마련했습니다.","인간의 적응과 부적응을 판단하는 기준을 제공한다":"인간행동 지식은 사람의 적응과 부적응을 판단하는 기준을 제공합니다.","인간집단의 생활양식의 총체로 정의할 수 있다":"문화는 인간 집단이 살아가는 생활양식 전체를 가리킵니다.","인간행동은 내적 충동보다는 외적 자극에 반응하여 나타난다":"행동주의는 사람의 행동이 내적 충동보다 외부 자극에 반응해 나타난다고 봅니다.","인간행동은 예측 가능하며 통제할 수 있다":"행동주의는 인간행동을 예측할 수 있고 통제할 수 있다고 봅니다.","인간행동의 무의식적 측면을 심층적으로 분석할 수 있는 기반을 제공하였다":"프로이트는 인간행동에 숨은 무의식을 깊이 분석할 기반을 마련했습니다.","자기 부양 능력을 갖추어야 하는 시기이다":"청년기는 스스로 먹고살 수 있는 자기 부양 능력을 갖추어야 하는 시기입니다.","자신의 감정이나 경험이 매우 특별하다고 생각한다":"청소년은 자기 감정이나 경험이 매우 특별하다고 여깁니다.","자신이 타인으로부터 집중적인 관심의 대상이 된다고 믿는다":"청소년은 자기가 타인에게서 집중적인 관심을 받는다고 믿습니다.","정서의 변화가 심하며 극단적 정서를 경험하기도 한다":"청소년기에는 정서 변화가 심해 극단적인 정서를 겪기도 합니다.","정해진 시간 간격이 지난 후 강화를 주는 것이다":"고정간격계획은 정해진 시간이 지난 뒤에 강화를 주는 방식입니다.","주류와 비주류 문화 사이의 권력 차이로 차별이 발생할 수 있다":"주류 문화와 비주류 문화 사이에 권력 차이가 있으면 차별이 생길 수 있습니다.","죽음과 상실에 대한 심리적 5단계를 제시하였다":"퀴블러 로스는 죽음과 상실을 맞는 사람의 심리를 5단계로 나누어 제시했습니다.","중년기 이후의 발달을 이해하는데 도움을 제공하였다":"융의 이론은 중년기 이후의 발달을 이해하는 데 도움이 되었습니다.","직업 준비와 직업선택에 대한 의사결정을 하는 시기이다":"청년기는 직업을 준비하고 선택에 대한 의사결정을 하는 시기입니다.","집단무의식의 주요 구성요소이다":"원형은 집단무의식을 이루는 중요한 구성요소입니다.","집단의 구성 동기에 따라 자연집단과 형성집단으로 분류된다":"집단은 구성하게 된 동기에 따라 자연집단과 형성집단으로 나뉩니다.","체계가 목적 달성이 어려운 방식으로 움직이고 있다는 정보를 제공하여 체계의 변화를 도모한다":"부적 환류는 체계가 목적 달성이 어려운 방식으로 움직인다는 정보를 주어 변화를 이끕니다.","체계를 외부 환경과 구분 짓는 둘레를 말한다":"경계는 체계를 외부 환경과 구분 짓는 둘레입니다.","체계를 유지하고, 발전을 도모하고, 생존하는 것을 의미한다":"넥엔트로피는 체계가 유지되고 발전하며 살아남는 방향의 힘을 가리킵니다.","추상적 이론과 관념적 사상에 빠져 때로 부정적 정서를 경험한다":"추상적 이론이나 관념적 사상에 빠져 때때로 부정적 정서를 경험하는 것이 이 시기의 모습입니다.","코카인, 헤로인의 약물 등에 의존: 태아가 약물에 중독된 채로 태어날 수 있다":"임신부가 코카인이나 헤로인에 의존하면 태아가 약물에 중독된 채 태어날 수 있습니다.","클라이언트 사정을 위한 유용한 지식이다":"인간행동에 대한 지식은 클라이언트를 사정할 때 유용하게 쓰입니다.","클라이언트의 발달과업을 성취할 수 있도록 지원하는 근거가 된다":"발달과업에 대한 지식은 클라이언트가 과업을 성취하도록 돕는 근거가 됩니다.","타인과의 관계에서 친밀감을 형성하면서 결혼과 부모됨을 고려하는 시기이다":"청년기에는 타인과 친밀감을 형성하며 결혼과 부모가 되는 일을 생각합니다.","태아가 사망하거나 출생 시 조산, 저체중, 뇌손상 등이 발생 할 수 있다":"임신부가 방사선에 노출되면 태아가 사망하거나 조산, 저체중, 뇌손상이 생길 수 있습니다.","태아의 미숙아 출생률을 증가시킨다":"임신부의 흡연은 미숙아로 태어나는 비율을 높입니다.","특질은 자아이상(ego ideal)과 양심(conscience)으로 구성된다":"초자아의 특질은 자아이상과 양심으로 이루어집니다.","특징적 발달 중 하나로 성적 성숙이 있다":"청소년기의 특징적인 발달 중 하나는 성적 성숙입니다.","학습되고 전승되는 특징이 있다":"문화는 배워서 익히고 다음 세대로 전해지는 특징이 있습니다.","해독 기능이 없는 태아에게 축적되어 안면기형 등의 부작용을 초래 할 수 있다":"태아는 해독 기능이 없어 임신부가 마신 알코올이 쌓이고 안면기형 같은 부작용이 생길 수 있습니다.","혐오적인 사건을 표현하거나 긍정적인 강화물을 제거하는 것으로, 특정행동의 빈도를 감소시키는 결과를 초래한다":"벌은 혐오적인 사건을 주거나 긍정적 강화물을 없애서 특정 행동의 빈도를 줄입니다.","환경의 체계 수준별 개입 근거를 제시한다":"생태체계관점은 환경의 체계 수준별로 어디에 개입할지 근거를 줍니다.","후천적 학습에 의해 획득되는 특성이 있다":"문화는 태어난 뒤 배움으로 얻어지는 후천적 특성이 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
